<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Crypto;use App\Core\DB;use App\Core\Mailer;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\ContactMessage;use App\Models\Invoice;use App\Models\License;use App\Models\Order;use App\Models\Plan;use App\Models\User;final class CustomerController extends AdminController{public function index(Request $j):Response{$v=User::query()->where('role','customer')->search(['email','name','company','vat_number'],$j->str('q'))->orderBy('id','DESC');$Y=$v->paginate($this->pageNumber($j),25);return $this->view('admin/customers/index',['res'=>$Y,'q'=>$j->str('q'),'meta'=>['title'=>t('admin.customers')]]);}public function show(Request $T,string $z):Response{$o=User::find((int)$z);if(!$o){return $this->redirect('/admin/customers');}$j=License::forUser((int)$o['id']);foreach($j as&$v){$v['plan']=Plan::find((int)$v['plan_id']);}unset($v);return $this->view('admin/customers/show',['customer'=>$o,'licenses'=>$j,'orders'=>Order::forUser((int)$o['id']),'invoices'=>Invoice::forUser((int)$o['id']),'audit'=>AuditLog::castAll(AuditLog::query()->where('user_id',(int)$o['id'])->orderBy('id','DESC')->limit(20)->get()),'countries'=>\App\Controllers\CheckoutController::countries(),'meta'=>['title'=>$o['email']]]);}public function update(Request $b,string $F):Response{$A=User::find((int)$F);if(!$A){return $this->redirect('/admin/customers');}if($d=$this->validate($b,['name'=>'required|max:191','email'=>'required|email','country'=>'required|regex:/^[A-Z]{2}$/','vat_number'=>'vat|max:32'],'/admin/customers/'.$F)){return $d;}$v=User::findByEmail($b->str('email'));if($v&&(int)$v['id']!==(int)$A['id']){$this->flash('error',t('auth.email_taken'));return $this->redirect('/admin/customers/'.$F);}User::update((int)$A['id'],['name'=>$b->str('name'),'email'=>mb_strtolower($b->str('email')),'company'=>$b->str('company')?:null,'vat_number'=>$b->str('vat_number')?:null,'address_line1'=>$b->str('address_line1')?:null,'address_line2'=>$b->str('address_line2')?:null,'postal_code'=>$b->str('postal_code')?:null,'city'=>$b->str('city')?:null,'country'=>strtoupper($b->str('country')),'phone'=>$b->str('phone')?:null,'is_active'=>$b->bool('is_active')?1:0]);if($b->bool('reset_2fa')){User::update((int)$A['id'],['two_factor'=>'none','totp_secret'=>null]);}AuditLog::log('admin.customer_update',$A['email']);$this->flash('success',t('common.saved'));return $this->redirect('/admin/customers/'.$F);}public function sendReset(Request $C,string $U):Response{$H=User::find((int)$U);if($H){$D=Crypto::randomToken();DB::insert('password_resets',['user_id'=>(int)$H['id'],'token_hash'=>Crypto::hashToken($D),'expires_at'=>gmdate('Y-m-d H:i:s',time()+3600),'created_at'=>now()]);(new Mailer())->sendTemplate($H['email'],'password_reset',['user'=>$H,'reset_url'=>url('/reset-password/'.$D,$H['lang']?:'fr')],$H['lang']?:'fr',$H['name']);AuditLog::log('admin.reset_sent',$H['email']);$this->flash('success',t('auth.reset_sent'));}return $this->redirect('/admin/customers/'.$U);}public function messages(Request $e):Response{$b=ContactMessage::query()->orderBy('id','DESC')->paginate($this->pageNumber($e),25);return $this->view('admin/messages',['res'=>$b,'meta'=>['title'=>t('admin.messages')]]);}public function messageRead(Request $q,string $i):Response{ContactMessage::update((int)$i,['read_at'=>now()]);return $this->redirect('/admin/messages');}}